import { Card, Col, Row, Form, Spinner } from 'react-bootstrap';
import Chart from 'react-apexcharts';
import React, { useState, useEffect } from 'react';
import { emiCalculation, calculateTotalInterestPayable, numberWithCommas, findArrObj } from '../../utils/AllFunction';
import Statistics from '../../pages/dashboards/DashBoard1/Statistics';
import CompanyDetails from '../../components/Atom/CompanyDetails';
import { usePageTitle, useRedux } from '../../hooks';
import { getDashboardRequest, resetGetDashboard } from '../../redux/actions';
import { Bar, Pie } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    ArcElement,
    BarElement,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';
import { Link } from 'react-router-dom';
import StatisticsWidget2 from '../../components/StatisticsWidget2';
import StatisticsWidget1 from '../../components/StatisticsWidget1';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../api/ApiConfig';
import moment from 'moment';
import Table from '../../components/Table';

ChartJS.register(CategoryScale, LinearScale, PointElement, BarElement, ArcElement, Title, Tooltip, Legend);

const Index = () => {

    usePageTitle({
        title: 'Dashboard',
        breadCrumbItems: [
            {
                path: '/dashboard',
                label: 'Dashboard',
            },
            {
                path: '/dashboard',
                label: 'Home',
                active: true,
            },
        ],
    });

    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, "url", "/dashboard");
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId;
    const canSeeAllBranches = roleIdforRole == 1  || accessIds.includes('3') || accessIds.includes('8');

    const { dispatch, appSelector } = useRedux();

    const { getDashboardSuccess, getDashboardList, getDashboardFailure,
        errorMessage,

    } = appSelector((state) => ({
        getDashboardSuccess: state.dashboardReducer.getDashboardSuccess,
        getDashboardList: state.dashboardReducer.getDashboardList,
        getDashboardFailure: state.dashboardReducer.getDashboardFailure,

        errorMessage: state.dashboardReducer.errorMessage,
    }));

    const [state, setState] = useState({
        loanAmount: 0,
        interestRate: 0,
        loanTenure: 0,
    });

    const [dashboardState, setDashboardState] = useState({});
    const [isLoading, setIsLoading] = useState(false);



    const donutChartData = {
        labels: ['Present', 'Absent', 'Half Day', 'Attendance Not Entry'],
        datasets: [
            {
                fill: true,
                data: [dashboardState?.attendanceListOut?.attendanceListCount?.
                    presentEmployeeCount, dashboardState?.attendanceListOut?.attendanceListCount?.
                    absentEmployeeCount, dashboardState?.attendanceListOut?.attendanceListCount?.halfDayEmployeeCount, dashboardState?.attendanceListOut?.attendanceListCount?.
                    attendanceNotEntryCount],
                backgroundColor: ['#ff8acc', '#5b69bc', '#ffc107', '#607d8b'],
                borderColor: '#fff',
            },
        ],
    };

    // default options
    const donutChartOpts = {
        maintainAspectRatio: false,
        cutoutPercentage: 800,
        plugins: {
            legend: {
                display: true,
            },
        },
    };

    const columns = [
        {
            Header: 'Staff Name',
            accessor: 'staffName',
            Cell: ({ row }) => <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <img
                    src={row?.original?.staffProfile ? `${baseURL}${row?.original?.staffProfile}` : noProfile}
                    alt="staffProfile"
                    style={{ width: "40px", height: "40px", borderRadius: "50%", objectFit: "cover" }}
                    crossOrigin="anonymous"
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = noProfile;
                    }}
                />
                <div style={{ textAlign: 'center', marginTop: '5px', fontSize: '14px' }}>
                    <div>{row?.original?.staffName}</div>
                    <div style={{ fontSize: '12px', color: '#666' }}>({row?.original?.staffCode})</div>
                </div>
            </div>,
        },
    ];


    // chart data
    const generateColors = (count) => {
        const colors = [];
        for (let i = 0; i < count; i++) {
            const hue = (i * 360 / count) % 360;
            colors.push(`hsl(${hue}, 60%, 55%)`);
        }
        return colors;
    };

    const roleData = dashboardState?.roleCount || [];
    const roleLabels = roleData.map(item => item.roleName);
    const roleCounts = roleData.map(item => item.roleCount);
    const dynamicColors = generateColors(roleData.length);

    const apexOpts = {
        chart: {
            type: 'donut',
        },
        plotOptions: {
            pie: {
                expandOnClick: true,
                donut: {
                    labels: {
                        show: true,
                        name: {
                            show: true,
                            formatter: (val) => val,
                            offsetY: 4,
                            color: '#98a6ad',
                        },
                        value: {
                            show: true,
                            formatter: (val) => val,
                            color: '#98a6ad',
                        },
                    },
                },
            },
        },
        dataLabels: {
            enabled: false,
        },
        colors: dynamicColors, // <--- dynamic colors here
        legend: {
            show: true,
            position: 'bottom',
            height: 40,
            labels: {
                useSeriesColors: true,
            },
        },
        labels: roleLabels,
        tooltip: {
            enabled: false,
        },
    };

    const apexData = roleCounts;


    // Bar Chart
    const barChartData = {
        labels: (dashboardState?.branchCount || []).map(branch => branch.branchName),
        datasets: [
            {
                label: 'Branch Analytics',
                data: (dashboardState?.branchCount || []).map(branch => branch.branchCount),
                backgroundColor: 'rgba(246, 114, 167, 0.2)',
                borderColor: '#f672a7',
                borderWidth: 1,
            },
        ],
    };
    const barChartOpts = {
        maintainAspectRatio: false,
        plugins: {
            legend: {
                display: true,
            },
        },
        scales: {
            y: {
                beginAtZero: false,
                grid: {
                    display: false,
                    drawBorder: false,
                },
                stacked: false,
                ticks: {
                    stepSize: 20,
                },
            },
            x: {
                stacked: false,
                grid: {
                    drawBorder: false,
                    color: () => 'rgba(0,0,0,0.01)',
                },
            },
        },
    };



    useEffect(() => {
        setIsLoading(true);
        const req = {
            branchId: branchIdforRole
        }
        dispatch(getDashboardRequest(!canSeeAllBranches && req));
    }, []);

    useEffect(() => {
        if (getDashboardSuccess) {
            setIsLoading(false)
            setDashboardState(getDashboardList)
            dispatch(resetGetDashboard())
        } else if (getDashboardFailure) {
            dispatch(resetGetDashboard())
        }
    }, [getDashboardSuccess, getDashboardFailure]);


    const active = dashboardState?.activeAndClosedLoanCount?.activeLoanCount || 0;
    const prevActive = dashboardState?.activeAndClosedLoanCount?.prevActiveLoanCount || 0;
    const closed = dashboardState?.activeAndClosedLoanCount?.closedLoanCount || 0;
    const prevClosed = dashboardState?.activeAndClosedLoanCount?.prevClosedLoanCount || 0;

    const getTrend = (current, previous) => {
        if (previous === 0) return current > 0 ? 100 : 0;
        return Math.round(((current - previous) / previous) * 100);
    };

    const activeTrend = getTrend(active, prevActive);
    const closedTrend = getTrend(closed, prevClosed);

    return (
        <React.Fragment>
            {/* <Statistics /> */}
            {isLoading ? (
                <div className="bg-light opacity-0.25">
                    <div className="d-flex justify-content-center m-5">
                        <Spinner className="mt-5 mb-5" animation="border" />
                    </div>
                </div>
            ) : (
                <>
                    <CompanyDetails fontSize="14px" imgSize="200px" borderBottom={false} classStyle="d-flex justify-content-center flex-column align-items-center" />
                    {/* Attendance Chart and Active and closed loan  and last one week staff leave report */}
                    <Row className='mt-5'>
                        <Col xl={6}>
                            <Card>
                                <Card.Body>
                                    <h4 className="header-title">Today Attendance Status</h4>
                                    <div className="mt-4 chartjs-chart" style={{ height: '350px' }}>
                                        <Pie data={donutChartData} options={donutChartOpts} />
                                    </div>
                                </Card.Body>
                            </Card>
                        </Col>
                        <Col xl={6}>
                            {
                                canSeeAllBranches &&
                                <Row>
                                    <Col xl={6} md={12}>
                                        <StatisticsWidget2
                                            variant="success"
                                            title="Active Loan"
                                            trendValue={`${activeTrend > 0 ? '+' : ''}${activeTrend}%`}
                                            trendIcon="mdi mdi-trending-up"
                                            stats={dashboardState?.activeAndClosedLoanCount?.activeLoanCount || 0}
                                            subTitle="Active"
                                            progress={Math.round((active / (active + closed || 1)) * 100)}
                                        />
                                    </Col>
                                    <Col xl={6} md={12}>
                                        <StatisticsWidget2
                                            variant="pink"
                                            title="Closed Loan"
                                            trendValue={`${activeTrend > 0 ? '+' : ''}${activeTrend}%`}
                                            trendIcon="mdi mdi-trending-up"
                                            stats={dashboardState?.activeAndClosedLoanCount?.closedLoanCount || 0}
                                            subTitle="Closed"
                                            progress={Math.round((closed / (active + closed || 1)) * 100)}

                                        />
                                    </Col>
                                </Row>
                            }
                            <Card>
                                <Card.Body>
                                    <h4 className="header-title mb-3">Staff Leave – Last 7 Days</h4>
                                    <div className="inbox-widget" style={{
                                        height: canSeeAllBranches ? "158px" : "361px",
                                        overflowY: "auto",
                                        overflowX: "hidden",
                                        borderRadius: "6px",
                                        padding: "4px",
                                        backgroundColor: "#fff",
                                        scrollbarWidth: "none",       // Firefox
                                        msOverflowStyle: "none"
                                    }}>
                                        {(dashboardState?.staffLastOneWeekLeave || []).map((staff, index) => {
                                            return (
                                                <div className="inbox-item d-flex align-items-start" key={index.toString()}>
                                                    <div className="inbox-item-img me-3">
                                                        <img
                                                            src={staff?.staffProfile ? `${baseURL}${staff.staffProfile}` : noProfile}
                                                            alt="staffProfile"
                                                            className="rounded-circle"
                                                            crossOrigin="anonymous"
                                                            onError={(e) => {
                                                                e.target.onerror = null;
                                                                e.target.src = noProfile;
                                                            }}
                                                            style={{ width: "50px", height: "50px", objectFit: "cover" }}
                                                        />
                                                    </div>
                                                    <div className="flex-grow-1">
                                                        <h5 className="inbox-item-author mt-0 mb-1">{staff.staffName}</h5>
                                                        <p className="inbox-item-text mb-1">{staff.reason}</p>
                                                        <p className="inbox-item-text mb-1">
                                                            {moment(staff?.fromDate).format('DD-MM-YYYY')} - {moment(staff?.toDate).format('DD-MM-YYYY')}
                                                        </p>
                                                        <h6 className="inbox-item-date inbox-item-author mt-0 mb-0">Days: {staff.dayCount}</h6>
                                                    </div>
                                                </div>

                                            );
                                        })}
                                    </div>
                                </Card.Body>
                            </Card>
                        </Col>


                    </Row>

                    {/* Attendance Not entry list */}
                    <Row className="mt-2" >
                        <Col xl={2}>
                            <div style={{
                                height: "453px",
                                overflowY: "auto",
                                overflowX: "hidden",
                                border: "1px solid #e0e0e0",
                                borderRadius: "6px",
                                padding: "4px",
                                backgroundColor: "#fff",
                                scrollbarWidth: "none",
                                msOverflowStyle: "none"
                            }}
                            >
                                <Table
                                    columns={[
                                        {
                                            ...columns[0],
                                            Header: "Present"
                                        }
                                    ]}
                                    data={dashboardState?.attendanceListOut?.presentEmployeeList || []}
                                    pagination={false}
                                    isSearchable={false}
                                />
                            </div>
                        </Col>
                        <Col xl={2}>
                            <div style={{
                                height: "453px",
                                overflowY: "auto",
                                overflowX: "hidden",
                                border: "1px solid #e0e0e0",
                                borderRadius: "6px",
                                padding: "4px",
                                backgroundColor: "#fff",
                                scrollbarWidth: "none",       // Firefox
                                msOverflowStyle: "none"
                            }}
                            >
                                <Table
                                    columns={[
                                        {
                                            ...columns[0],
                                            Header: "Absent"
                                        }
                                    ]}
                                    data={dashboardState?.attendanceListOut?.absentEmployeeList || []}
                                    pagination={false}
                                    isSearchable={false}
                                />
                            </div>
                        </Col>
                        <Col xl={2}>
                            <div style={{
                                height: "453px",
                                overflowY: "auto",
                                overflowX: "hidden",
                                border: "1px solid #e0e0e0",
                                borderRadius: "6px",
                                padding: "4px",
                                backgroundColor: "#fff",
                                scrollbarWidth: "none",       // Firefox
                                msOverflowStyle: "none"
                            }}
                            >
                                <Table
                                    columns={[
                                        {
                                            ...columns[0],
                                            Header: "Halfday"
                                        }
                                    ]}
                                    data={dashboardState?.attendanceListOut?.halfDayEmployeeList || []}
                                    pagination={false}
                                    isSearchable={true}
                                />
                            </div>
                        </Col>
                        <Col xl={2}>
                            <div style={{
                                height: "453px",
                                overflowY: "auto",
                                overflowX: "hidden",
                                border: "1px solid #e0e0e0",
                                borderRadius: "6px",
                                padding: "4px",
                                backgroundColor: "#fff",
                                scrollbarWidth: "none",       // Firefox
                                msOverflowStyle: "none"
                            }}
                            >
                                <Table
                                    columns={[
                                        {
                                            ...columns[0],
                                            Header: "No Attendance marked"
                                        }
                                    ]}
                                    data={dashboardState?.attendanceListOut?.attendanceNotEntryList || []}
                                    pagination={false}
                                    isSearchable={true}
                                />
                            </div>
                        </Col>

                        <Col xl={4}>
                            <Card>
                                <Card.Body>
                                    <h4 className="header-title">Branch Analytics</h4>
                                    <div style={{ height: '350px' }} className="mt-4 chartjs-chart">
                                        <Bar data={barChartData} options={barChartOpts} />
                                    </div>
                                </Card.Body>
                            </Card>
                        </Col>
                    </Row>




                    {/* Role Analytics */}
                    <Row className="mt-3">
                        <Col xs={12} md={6}>
                            <Card>
                                <Card.Body style={{ display: "flex", justifyContent: "center", flexDirection: "column" }}>
                                    <h4 className="header-title mt-0">Role Analytics</h4>
                                    <div dir="ltr">
                                        <Chart
                                            options={apexOpts}
                                            series={apexData}
                                            type="donut"
                                            height={400}
                                            className="apex-charts mt-2"
                                        />
                                    </div>
                                </Card.Body>
                            </Card>
                        </Col>
                        {
                            canSeeAllBranches &&
                            <Col xs={12} md={6}>
                                <Card>
                                    <Card.Body>
                                        <h4 className="header-title mt-0 mb-4">Next Birthday Employee ({moment(dashboardState?.upComingBirthday?.nextBirthdayDate || null).format('DD-MM-YYYY')})</h4>
                                        <Card.Body style={{ height: '350px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center' }}>

                                            <img
                                                src={dashboardState?.upComingBirthday?.staffProfile ? `${baseURL}${dashboardState?.upComingBirthday?.staffProfile}` : noProfile}
                                                alt="staffProfile"
                                                style={{ width: "200px", height: "200px", borderRadius: "50%", objectFit: "cover" }}
                                                crossOrigin="anonymous"
                                                onError={(e) => {
                                                    e.target.onerror = null;
                                                    e.target.src = noProfile;
                                                }}
                                            />

                                            <div style={{ textAlign: 'center', marginTop: '10px' }}>
                                                <div style={{ fontSize: '16px', fontWeight: 600 }}>
                                                    {dashboardState?.upComingBirthday?.staffName}
                                                </div>
                                                <div style={{ fontSize: '13px', color: '#888' }}>
                                                    ({dashboardState?.upComingBirthday?.staffCode})
                                                </div>
                                            </div>

                                            <div
                                                style={{
                                                    marginTop: 'auto',
                                                    fontStyle: 'italic',
                                                    fontSize: '15px',
                                                    textAlign: 'center',
                                                    background: 'linear-gradient(to right, #ec008c, #fc6767)',
                                                    WebkitBackgroundClip: 'text',
                                                    WebkitTextFillColor: 'transparent',
                                                    display: 'inline-block',
                                                }}
                                            >
                                                <i className="fe-gift" style={{ marginRight: '5px', color: '#fc6767', fontSize: '16px' }}></i>
                                                Wishing you joy, success and a fantastic birthday ahead!
                                            </div>
                                        </Card.Body>
                                    </Card.Body>
                                </Card>
                            </Col>
                        }
                    </Row>



                </>
            )
            }

        </React.Fragment>
    );
};

export default Index;

